function renderBlocksHtml(blocks) {
  const ARROW = '<svg viewBox="0 0 16 16" fill="none" style="width:14px;height:14px;vertical-align:-2px"><path d="M3 8h10M9 4l4 4-4 4" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>';
  return blocks.map(b => {
    switch (b.t) {
      case 'h2': return `<h2 style="font-family:'InterVariable','Inter',sans-serif;font-feature-settings:'cv11' 1;font-weight:500;letter-spacing:-.02em;color:#F7F6F4;font-size:clamp(1.5rem,2.7vw,2.1rem);margin:clamp(48px,6vw,72px) 0 20px">${b.x}</h2>`;
      case 'h3': return `<h3 style="font-family:'InterVariable','Inter',sans-serif;font-feature-settings:'cv11' 1;font-weight:500;letter-spacing:-.015em;color:#F7F6F4;margin:36px 0 14px;font-size:1.16rem">${b.x}</h3>`;
      case 'p': return `<p style="font-family:'InterVariable','Inter',sans-serif;font-feature-settings:'cv11' 1;font-weight:400;color:rgba(255,255,255,.64);font-size:1.03rem;line-height:1.5;margin-bottom:18px">${b.x}</p>`;
      case 'ul': return `<ul style="list-style:none;padding:0;margin:0 0 20px;display:grid;gap:12px">${b.x.map(i => `<li style="display:flex;gap:12px;color:rgba(255,255,255,.64);line-height:1.5"><span style="width:5px;height:5px;margin-top:.6em;flex:none;border-radius:50%;background:rgba(255,255,255,.64);opacity:.7"></span><span>${i}</span></li>`).join('')}</ul>`;
      case 'f': return `<div>${b.x.map(r => `<div style="display:grid;grid-template-columns:minmax(170px,.42fr) 1fr;gap:22px;padding:22px 0;border-top:1px solid rgba(255,255,255,.06)"><span style="font-weight:500;letter-spacing:-.013em;color:#F7F6F4">${r[0]}</span><span style="color:rgba(255,255,255,.64);font-size:.98rem">${r[1]}</span></div>`).join('')}<div style="border-bottom:1px solid rgba(255,255,255,.06)"></div></div>`;
      case 'tags': return `<div style="display:flex;flex-wrap:wrap;gap:9px;margin:22px 0 6px">${b.x.map(t => `<span style="display:inline-flex;align-items:center;padding:8px 15px;border-radius:100px;background:rgba(255,255,255,.08);color:#F7F6F4;font-family:'InterVariable','Inter',sans-serif;font-size:15px;font-weight:400;white-space:nowrap;pointer-events:none">${t}</span>`).join('')}</div>`;
      case 'stats': return `<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:14px;margin:64px 0 24px">${b.x.map(s => `<div style="padding:26px;border-radius:14px;border:1px solid rgba(255,255,255,.06);background:rgba(255,255,255,.032)"><b style="display:block;font-family:'InterVariable','Inter',sans-serif;font-feature-settings:'cv11' 1;font-size:clamp(1.6rem,3vw,2.2rem);font-weight:600;letter-spacing:-.028em;line-height:1;margin-bottom:12px;color:#F7F6F4">${s[0]}</b><span style="color:rgba(255,255,255,.64);font-size:.88rem">${s[1]}</span></div>`).join('')}</div>`;
      case 'q': return `<blockquote style="margin:60px 0;padding:30px 32px;border-radius:14px;border:1px solid rgba(255,255,255,.06);background:rgba(255,255,255,.032);position:relative"><p style="font-family:'InterVariable','Inter',sans-serif;font-feature-settings:'cv11' 1;color:#F7F6F4;font-size:clamp(1.08rem,1.9vw,1.4rem);font-weight:500;letter-spacing:-.017em;line-height:1.35;margin:0">${b.x}</p>${b.by ? `<cite style="display:block;margin-top:16px;font-style:normal;font-size:.86rem;color:rgba(255,255,255,.64)">— ${b.by}</cite>` : ''}</blockquote>`;
      case 'img': {
        const media = b.src ? '<img src="' + b.src + '" alt="' + (b.cap || '') + '" style="width:100%;aspect-ratio:16/10;object-fit:cover;display:block">' : viz(b.kind, b.seed);
        return `<figure style="margin:34px 0;border-radius:22px;overflow:hidden;border:1px solid rgba(255,255,255,.06);background:rgba(255,255,255,.032)">${media}<figcaption style="padding:14px 20px;font-size:.82rem;color:rgba(255,255,255,.64);border-top:1px solid rgba(255,255,255,.06)">${b.cap}</figcaption></figure>`;
      }
      case 'hash': return `<p style="font-family:'JetBrains Mono',monospace;font-size:.78rem;color:rgba(255,255,255,.64);line-height:1.9;margin-top:30px;word-spacing:.2em">${b.x}</p>`;
      default: return '';
    }
  }).join('');
}


if (typeof window !== "undefined") { window.SOFTBEES_DATA = { PRODUCTS, CASES, POSTS, CATEGORIES, PARENTS, DETAILS, viz, vizPlain, renderBlocksHtml }; }
